function comboPairRisk(a,b){if(!a||!b)return 0;if(String(a.e.id)===String(b.e.id)){var ga=comboGroup(a.o),gb=comboGroup(b.o);if(ga===gb)return.9;if((ga==='result'&&gb==='goals')||(gb==='result'&&ga==='goals'))return.78;if(ga==='player'||gb==='player')return.72;return.62}var ta=[normPlayer(a.e.home_team),normPlayer(a.e.away_team)],tb=[normPlayer(b.e.home_team),normPlayer(b.e.away_team)];return ta.some(function(x){return x&&tb.includes(x)})?.30:0}
function independentTake(pool,target){var legs=[];(pool||[]).some(function(x){var max=legs.reduce(function(r,y){return Math.max(r,comboPairRisk(x,y))},0);if(max>=.70)return false;legs.push(x);return legs.length>=target});return legs}
