function superiorCombos(){var configs=[{name:'BLINDAJE POSITIVO',legs:2,min:.03,tone:'#b7f34a'},{name:'SUPERIOR BALANCE',legs:3,min:.02,tone:'#58d9ff'},{name:'POTENCIA SELECTA',legs:4,min:.001,tone:'#ffc45c'}],pool=rated().filter(function(x){return x.o.edge>0&&x.score>=68});return'<div class="superior-title"><h2>Combinadas superiores</h2><span>Solo margen positivo · mejores stakes</span></div><div class="combo-grid">'+configs.map(function(c){var legs=independentTake(pool.filter(function(x){return x.o.edge>=c.min}),c.legs),odds=legs.reduce(function(a,x){return a*x.o.price},1),prob=comboStats(legs).prob,margin=legs.length?legs.reduce(function(a,x){return a+x.o.edge},0)/legs.length:0,stake=legs.length===c.legs?(c.legs===2?4:c.legs===3?3:2):0;return'<article class="card combo" style="--tone:'+c.tone+'"><header><h3>'+c.name+'</h3><span class="positive">Margen +'+(margin*100).toFixed(1)+'%</span></header>'+(legs.length===c.legs?legs.map(function(x){return'<div class="combo-leg"><b>'+esc(x.e.home_team)+' vs '+esc(x.e.away_team)+'</b>'+pickInfo(x.o,'Cuota '+x.o.price.toFixed(2)+' · Acierto '+Math.round(x.o.prob*100)+'%')+'</div>'}).join(''):'<div class="combo-leg"><span>Faltan selecciones con margen positivo suficiente.</span></div>')+'<div class="combo-summary"><div><small>Cuota</small><b>'+odds.toFixed(2)+'</b></div><div><small>Acierto est.</small><b>'+Math.round(prob*100)+'%</b></div><div><small>Stake</small><b>'+stake+'/5</b></div></div></article>'}).join('')+'</div>'}
