function playerComboPool(){var rows=[];S.events.forEach(function(e){var consensus=cons(e);best(e).filter(function(o){return playerMarket(o.market)}).forEach(function(o){var k=o.market+'|'+(o.description||'')+'|'+o.name+'|'+(o.point==null?'':o.point),marketProb=consensus[k]||1/o.price,model=playerModel(e,o),prob=model?marketProb*(1-model.weight)+model.prob*model.weight:marketProb,edge=prob*o.price-1,player=String(o.description||o.name||'Jugador').trim(),books=(e.bookmakers||[]).filter(function(b){return(b.markets||[]).some(function(m){return m.key===o.market&&(m.outcomes||[]).some(function(x){return String(x.description||'')===String(o.description||'')&&x.name===o.name&&String(x.point==null?'':x.point)===String(o.point==null?'':o.point)})})}).length;if(prob>=.30&&o.price>=1.15&&edge>0&&books>=1&&marketHealth(o.market).state!=='paused')rows.push({e:e,o:Object.assign({},o,{prob:prob,edge:edge,playerLabel:model&&model.label}),player:player,books:books,mode:model?'MODELO JUGADOR':'CONSENSO MERCADO',rank:prob+Math.min(.20,edge)+Math.min(books,8)*.006})})});return rows.sort(function(a,b){return b.rank-a.rank})}
function buildPlayerTicket(pool,target,offset){var legs=[],events={},players={};for(var i=offset||0;i<pool.length&&legs.length<target;i++){var x=pool[i],pk=normPlayer(x.player);if(events[x.e.id]||players[pk]||legs.some(function(y){return comboPairRisk(x,y)>=.70}))continue;events[x.e.id]=1;players[pk]=1;legs.push(x)}return legs}
