function buildUniqueTicket(pool,target,context){var used={},legs=[];pool.slice().sort(function(a,b){return seeded(b.e.id+'|'+context+'|'+S.seed)-seeded(a.e.id+'|'+context+'|'+S.seed)}).forEach(function(x){if(legs.length>=target||used[x.e.id]||legs.some(function(y){return comboPairRisk(x,y)>=.70}))return;used[x.e.id]=1;legs.push(x)});return legs}
function uniqueComboCard(name,badge,tone,legs,note){var odds=legs.reduce(function(a,x){return a*x.o.price},1),prob=comboStats(legs).prob,avgPrice=legs.length?legs.reduce(function(a,x){return a+x.o.price},0)/legs.length:0;return'<article class="card combo" style="--tone:'+tone+'"><header><div><h3>'+name+'</h3><small>'+note+'</small></div><span class="positive">'+badge+'</span></header>'+(legs.length?legs.map(function(v){return'<div class="combo-leg"><b>'+esc(v.e.home_team)+' vs '+esc(v.e.away_team)+'</b>'+pickInfo(v.o,'Cuota '+v.o.price.toFixed(2)+' · Prob. '+(v.o.prob*100).toFixed(1)+'%')+'</div>'}).join(''):'<div class="combo-leg"><span>No hay suficientes selecciones elegibles para este perfil.</span></div>')+'<div class="combo-summary"><div><small>Cuota total</small><b>'+(legs.length?odds.toFixed(2):'—')+'</b></div><div><small>Prob. comb.</small><b>'+(legs.length?(prob*100).toFixed(1)+'%':'—')+'</b></div><div><small>Cuota media</small><b>'+(legs.length?avgPrice.toFixed(2):'—')+'</b></div></div>'+corrBadge(legs)+'</article>'}
function uniqueCombos(){var base=rated('unique').filter(function(x){return x.o.edge>0&&x.o.prob>=.42}),randomLegs=buildUniqueTicket(base,4,'random'),safePool=base.filter(function(x){return x.o.prob>=.60&&x.o.price>=1.15&&x.o.price<=1.70}).sort(function(a,b){return b.o.prob-a.o.prob||b.score-a.score}),safeLegs=buildUniqueTicket(safePool,3,'safe'),conventionalPool=base.filter(function(x){return x.o.prob>=.46&&x.o.price>=1.45&&x.o.price<=2.20}).sort(function(a,b){return b.score-a.score}),conventionalLegs=buildUniqueTicket(conventionalPool,3,'conventional'),hero='<div class="combo-hero unique-hero"><div><small>RANDOMIZED VALUE DESK</small><h2>🎲 COMBINADAS ÚNICAS</h2><p>Tres perfiles · partidos distintos · Barajar cambia la mezcla sin consumir créditos</p></div><b>NUEVO</b></div>';if(!base.length)return hero+'<div class="card empty"><h2>Sin picks elegibles</h2><p>Consulta partidos con EV positivo para generar combinadas únicas.</p></div>';return hero+'<div class="combo-grid">'+uniqueComboCard('UNIQUE '+randomLegs.length,'MEZCLA ÚNICA','#ffb62e',randomLegs,'Rotación aleatoria con EV positivo')+uniqueComboCard('CUOTAS SEGURAS',safeLegs.length+' PICKS','#56e38b',safeLegs,'Perfil conservador: probabilidad alta y cuota moderada · no garantiza acierto')+uniqueComboCard('CUOTAS CONVENCIONALES',conventionalLegs.length+' PICKS','#3ea6ff',conventionalLegs,'Perfil balanceado: cuotas habituales y EV positivo')+'</div>'}
